<?php
namespace App\Http\Controllers\Api\V1; use App\Enums\UserRole;use App\Http\Controllers\Controller;use App\Models\{TaxClass,TaxJurisdiction,TaxRate,Vendor,VendorTaxProfile};use Illuminate\Http\{JsonResponse,Request};use Illuminate\Support\Str;use Illuminate\Validation\Rule; class AdminTaxController extends Controller { private function admin(Request $r):void{$v=$r->user()?->role instanceof UserRole?$r->user()->role->value:(string)$r->user()?->role;abort_unless(in_array($v,[UserRole::Finance->value,UserRole::Admin->value,UserRole::SuperAdmin->value],true),403);} public function index(Request $r):JsonResponse{$this->admin($r);return response()->json(['data'=>['jurisdictions'=>TaxJurisdiction::query()->with('rates.taxClass')->orderBy('country_code')->orderBy('region_code')->get()->map(/** Inline callback for this operation. */ fn($j)=>['id'=>$j->public_id,'name'=>$j->name,'countryCode'=>$j->country_code,'regionCode'=>$j->region_code,'status'=>$j->status,'rates'=>$j->rates->map(/** Inline callback for this operation. */ fn($x)=>$this->rateRow($x))->all()]),'classes'=>TaxClass::query()->orderBy('name')->get()->map(/** Inline callback for this operation. */ fn($c)=>['id'=>$c->public_id,'code'=>$c->code,'name'=>$c->name,'default'=>$c->is_default,'status'=>$c->status]),'vendorProfiles'=>VendorTaxProfile::query()->with('vendor')->latest()->limit(200)->get()->map(/** Inline callback for this operation. */ fn($p)=>['id'=>$p->public_id,'vendor'=>$p->vendor?->name,'status'=>$p->status,'registeredName'=>$p->registered_name,'taxIdentifierLast4'=>$p->tax_identifier_last4,'countryCode'=>$p->registration_country_code,'collectionMode'=>$p->collection_mode,'priceIncludesTax'=>$p->price_includes_tax])]]);} public function jurisdiction(Request $r):JsonResponse{$this->admin($r);$d=$r->validate(['countryCode'=>'required|string|size:2','regionCode'=>'nullable|string|max:100','name'=>'required|string|max:160','status'=>'nullable|in:active,inactive','priority'=>'nullable|integer|min:0|max:10000']);$j=TaxJurisdiction::query()->firstOrNew(['country_code'=>strtoupper($d['countryCode']),'region_code'=>$d['regionCode']??null]);$j->public_id=$j->public_id?:((string)Str::ulid());$j->fill(['name'=>$d['name'],'status'=>$d['status']??'active','priority'=>$d['priority']??100])->save();return response()->json(['data'=>['id'=>$j->public_id,'name'=>$j->name]],201);} public function taxClass(Request $r):JsonResponse{$this->admin($r);$d=$r->validate(['code'=>'required|string|max:80','name'=>'required|string|max:160','description'=>'nullable|string|max:1000','isDefault'=>'nullable|boolean']);if($d['isDefault']??false)TaxClass::query()->update(['is_default'=>false]);$c=TaxClass::query()->firstOrNew(['code'=>strtolower($d['code'])]);$c->public_id=$c->public_id?:((string)Str::ulid());$c->fill(['name'=>$d['name'],'description'=>$d['description']??null,'is_default'=>$d['isDefault']??false,'status'=>'active'])->save();return response()->json(['data'=>['id'=>$c->public_id,'code'=>$c->code,'name'=>$c->name]],201);} public function rate(Request $r):JsonResponse{$this->admin($r);$d=$r->validate(['jurisdictionId'=>'required|string|exists:tax_jurisdictions,public_id','taxClassId'=>'nullable|string|exists:tax_classes,public_id','appliesTo'=>['required',Rule::in(['product','shipping'])],'label'=>'required|string|max:120','rateBps'=>'required|integer|min:0|max:100000','validFrom'=>'nullable|date','validUntil'=>'nullable|date|after:validFrom']);$j=TaxJurisdiction::where('public_id',$d['jurisdictionId'])->firstOrFail();$c=!empty($d['taxClassId'])?TaxClass::where('public_id',$d['taxClassId'])->firstOrFail():null;if($d['appliesTo']==='shipping')$c=null;$x=TaxRate::create(['public_id'=>(string)Str::ulid(),'tax_jurisdiction_id'=>$j->id,'tax_class_id'=>$c?->id,'applies_to'=>$d['appliesTo'],'label'=>$d['label'],'rate_bps'=>$d['rateBps'],'status'=>'active','valid_from'=>$d['validFrom']??null,'valid_until'=>$d['validUntil']??null]);return response()->json(['data'=>$this->rateRow($x)],201);} public function updateRate(Request $r,TaxRate $rate):JsonResponse{$this->admin($r);$d=$r->validate(['label'=>'sometimes|string|max:120','rateBps'=>'sometimes|integer|min:0|max:100000','status'=>'sometimes|in:active,inactive','validFrom'=>'sometimes|nullable|date','validUntil'=>'sometimes|nullable|date']);$map=[];foreach(['label'=>'label','rateBps'=>'rate_bps','status'=>'status','validFrom'=>'valid_from','validUntil'=>'valid_until'] as $in=>$db)if(array_key_exists($in,$d))$map[$db]=$d[$in];if($map)$rate->update($map);return response()->json(['data'=>$this->rateRow($rate->fresh())]);} public function reviewVendor(Request $r,VendorTaxProfile $profile):JsonResponse{$this->admin($r);$d=$r->validate(['status'=>'required|in:active,rejected,suspended','collectionMode'=>'required|in:platform,seller,none','note'=>'nullable|string|max:1000']);$profile->update(['status'=>$d['status'],'collection_mode'=>$d['collectionMode'],'verified_at'=>$d['status']==='active'?now():null,'verified_by_user_id'=>$r->user()->id,'metadata'=>array_merge($profile->metadata??[],['review_note'=>$d['note']??null])]);return response()->json(['data'=>['id'=>$profile->public_id,'status'=>$profile->status,'collectionMode'=>$profile->collection_mode]]);} private function rateRow($x):array{return ['id'=>$x->public_id,'label'=>$x->label,'rateBps'=>$x->rate_bps,'appliesTo'=>$x->applies_to,'taxClass'=>$x->taxClass?->code,'status'=>$x->status,'validFrom'=>$x->valid_from?->toIso8601String(),'validUntil'=>$x->valid_until?->toIso8601String()];} }